const item = $input.first().json.body || $input.first().json;

const resourceId = item.resourceId || 'AMENITY-TENNIS-01';
const resourceName = item.resourceName || 'Floodlit Tennis Court';
const targetDate = item.targetDate || '2026-11-21';
const recentBookingHistory = item.recentBookingHistory || [
  { flatNo: 'Tower A-402', bookingsInLast7Days: 5, peakHourBookings: 4, noShowCount: 1 },
  { flatNo: 'Tower B-103', bookingsInLast7Days: 1, peakHourBookings: 1, noShowCount: 0 },
  { flatNo: 'Tower A-402', requestedSlot: '07:00 PM - 08:00 PM (Saturday)', isPeak: true }
];

const prompt = `You are the Chief Facility Auditor and Fair-Play Officer for Mana Community Amenities.
Audit the following amenity slot request and recent booking patterns for slot hoarding, monopolization, and unfair usage:

Amenity & Request Dossier:
- Amenity: ${resourceName} (${resourceId}) for ${targetDate}
- Society Bylaw Quotas: Max 3 bookings per week per flat (Max 2 peak-hour weekend slots).
- Current Booking History & Applicant Data:
${JSON.stringify(recentBookingHistory, null, 2)}

Audit Verification Criteria:
1. Quota Exhaustion: Has the applicant flat exceeded weekly peak/general booking limits?
2. Slot Monopolization: Are neighboring flats being starved of weekend prime slots?
3. No-Show Penalty: Check if applicant has repeat no-shows without 2-hour advance cancellation.
4. Decision: Issue "APPROVED", "STANDBY_WAITLIST", or "COOLDOWN_RESTRICTION".

Respond ONLY with a valid JSON object matching this schema:
{
  "fairnessVerdict": "APPROVED" | "STANDBY_WAITLIST" | "COOLDOWN_RESTRICTION",
  "fairnessScore": number (0 to 100),
  "quotaStatus": {
    "weeklyUsed": number,
    "weeklyAllowed": number,
    "peakHourLimitReached": boolean
  },
  "hoardingRisk": "LOW" | "MODERATE" | "HIGH",
  "restrictionReason": string,
  "recommendedAction": string,
  "residentNotice": string
}`;

return [{ json: { prompt, resourceId, resourceName } }];

const gemini = $input.first().json;
let parsed = {};
try {
  const raw = gemini.candidates[0].content.parts[0].text;
  parsed = JSON.parse(raw);
} catch (e) {
  parsed = {
    fairnessVerdict: "COOLDOWN_RESTRICTION",
    fairnessScore: 62,
    quotaStatus: { weeklyUsed: 5, weeklyAllowed: 3, peakHourLimitReached: true },
    hoardingRisk: "HIGH",
    restrictionReason: "Flat has exceeded the 3 bookings/week threshold with 4 peak-hour slots.",
    recommendedAction: "Apply 48-hour cooldown before permitting next prime-time reservation.",
    residentNotice: "You have utilized your weekly peak-hour allocation. This slot has been prioritized for waiting neighbors."
  };
}

const meta = $('Prepare AI Prompt').first().json;
return [{ json: { status: "success", resourceId: meta.resourceId, resource: meta.resourceName, auditedAt: new Date().toISOString(), evaluation: parsed } }];
